exercises.starter_code:
#include <stdio.h>

int main(void) {
    const char *s = "Go Programming";
    // toupper loop
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
#include <ctype.h>
#include <string.h>
    const char *s = "Go Programming";
    char up[32], lo[32];
    strcpy(up, s); strcpy(lo, s);
    for (char *p = up; *p; p++) *p = (char)toupper((unsigned char)*p);
    for (char *p = lo; *p; p++) *p = (char)tolower((unsigned char)*p);
    puts(up);
    puts(lo);
    return 0;
}

exercises.starter_code:
#include <stdio.h>

int main(void) {
    char s[] = "hello";
    // reverse in place
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <string.h>

int main(void) {
    char s[] = "hello";
    size_t n = strlen(s);
    for (size_t i = 0, j = n - 1; i < j; i++, j--) {
        char t = s[i]; s[i] = s[j]; s[j] = t;
    }
    puts(s);
    return 0;
}

exercises.starter_code:
#include <stdio.h>

int main(void) {
    const char *url = "https://example.com";
    // prefix/suffix
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
#include <string.h>
    const char *url = "https://example.com";
    printf("%s %s\n",
           strncmp(url, "https://", 8) == 0 ? "true" : "false",
           strcmp(url + strlen(url) - 4, ".com") == 0 ? "true" : "false");
    return 0;
}
